```sql
SELECT * FROM instruments WHERE instrument_id NOT LIKE 'I1%' OR guarantor_id<>'' ORDER BY instrument_id;
```

```sql
SELECT * FROM rating_actions WHERE rated_id NOT LIKE 'E1%' OR rated_id IN ('CV','VD') ORDER BY rated_id, date;
```

```sql
SELECT rating_type, count(*), min(date), max(date) FROM rating_actions GROUP BY ALL;
```

```sql
SELECT entity_id,name,country,entity_type,parent_id,source_system FROM entities WHERE entity_type NOT IN ('CORP','BANK','FINSUB') OR country IN ('LU','VD','CV') ORDER BY entity_id;
```

```sql
SELECT count(*) AS n, (SELECT count(*) FROM (SELECT DISTINCT * FROM rating_actions)) AS n_distinct, (SELECT count(DISTINCT action_id) FROM rating_actions) AS n_ids;
```

```sql
SELECT DISTINCT * FROM rating_actions WHERE rating_type IN ('CO','CC') ORDER BY date;
```

```sql
SELECT DISTINCT action_id, date, rated_id, ccy_basis, action, rating, comment FROM rating_actions WHERE rating IN ('RD','D','C','DDD','DD') OR comment<>'' ORDER BY date LIMIT 40;
```

```sql
SELECT DISTINCT action_id, date, rated_id, rating, outlook, watch FROM rating_actions WHERE rating_type='LTIDR' AND ccy_basis='FC' AND date<='2026-10-01' AND (watch='RWN' OR outlook='NEG') AND date>='2026-01-01' ORDER BY rated_id, date LIMIT 60;
